#!/bin/sh
# Reference XAdES and FacturaE signatures made by AutoFirma 1.9. They are not
# regenerated by a script, since they change on every run (random ids, time).
#
# - doc.xml:     XML document with a default namespace and non-ASCII text
# - doc.txt:     binary (non-XML) data, the same as tests/data/cades/doc.txt
# - factura.xml: FacturaE 3.2.2 invoice with test data
#
# They were made with:
#
#   AF="java -Djava.awt.headless=true -jar /usr/lib/Autofirma/autofirma.jar sign"
#   KEY="-store pkcs12:../certs/rsa.p12 -password 1234 -alias rsa"
#   $AF -format xades -i doc.xml -o autofirma-enveloping-rsa.xsig $KEY
#   $AF -format xades -i doc.xml -o autofirma-enveloped-rsa.xsig $KEY -config 'format=XAdES Enveloped'
#   $AF -format xades -i doc.xml -o autofirma-detached-rsa.xsig $KEY -config 'format=XAdES Detached'
#   $AF -format xades -i doc.txt -o autofirma-binary-enveloping-rsa.xsig $KEY
#   $AF -format xades -i doc.txt -o autofirma-binary-detached-rsa.xsig $KEY -config 'format=XAdES Detached'
#   $AF -format xades -i doc.xml -o autofirma-enveloped-age-rsa.xsig $KEY -config 'format=XAdES Enveloped\npolicyIdentifier=urn:oid:2.16.724.1.3.1.1.2.1.9\npolicyIdentifierHash=G7roucf600+f03r/o0bAOQ6WAs0=\npolicyIdentifierHashAlgorithm=http://www.w3.org/2000/09/xmldsig#sha1\npolicyQualifier=https://sede.administracion.gob.es/politica_de_firma_anexo_1.pdf\nsignatureProductionCity=Madrid\nsignerClaimedRoles=emisor'
#   $AF -format xades -i doc.xml -o autofirma-enveloped-ec.xsig -store pkcs12:../certs/ec.p12 -password 1234 -alias ec -config 'format=XAdES Enveloped'
#   $AF -format facturae -i factura.xml -o autofirma-facturae-rsa.xsig $KEY
#
# -config takes literal \n separators. Under the VS Code snap, run java with a clean
# environment (env -i PATH=/usr/bin:/bin java ...).
exit 0
